import Foundation

/// The trajectory generated by the Ruckig algorithm.
public struct Trajectory {
    var profiles: [[Profile]] = []

    var duration: Double = 0.0
    var cumulativeTimes: [Double] = []

    var independentMinDurations: [Double] = []
    var positionExtrema: [Bound] = []

    let degreesOfFreedom: Int

    public init(dofs: Int) {
        self.degreesOfFreedom = dofs
        self.profiles = [(0..<dofs).map { _ in Profile() }]
        self.cumulativeTimes = [0.0]
        self.independentMinDurations = Array(repeating: 0.0, count: dofs)
        self.positionExtrema = Array(repeating: Bound(), count: dofs)
    }

    public init(dofs: Int, maxNumberOfWaypoints: Int) {
        self.degreesOfFreedom = dofs
        self.profiles = (0..<(maxNumberOfWaypoints + 1)).map { _ in (0..<dofs).map { _ in Profile() } }
        self.cumulativeTimes = Array(repeating: 0.0, count: maxNumberOfWaypoints + 1)
        self.independentMinDurations = Array(repeating: 0.0, count: dofs)
        self.positionExtrema = Array(repeating: Bound(), count: dofs)
    }

    /// Calculates the base values to then integrate from
    /// returns 
    ///     - dof, 
    ///     - time, 
    ///     - position, 
    ///     - velocity, 
    ///     - acceleration, 
    ///     - jerk
    private func stateToIntegrateFrom(
        time: Double,
        newSection: inout Int,
        set_integrate: (Int, Double, Double, Double, Double, Double) -> Void
    ) {
        if time >= duration {
            // Keep constant acceleration
            newSection = profiles.count
            let profiles_dof = profiles.last!
            for dof in 0..<degreesOfFreedom {
                let t_pre =
                    (profiles.count > 1)
                    ? cumulativeTimes[cumulativeTimes.count - 2]
                    : profiles_dof[dof].brake.duration
                let t_diff = time - (t_pre + profiles_dof[dof].tSum.last!)
                set_integrate(
                    dof,
                    t_diff,
                    profiles_dof[dof].p.last!,
                    profiles_dof[dof].v.last!,
                    profiles_dof[dof].a.last!,
                    0.0
                )
            }
            return
        }

        // Find the correct section using upper_bound equivalent
        var section_index = cumulativeTimes.count
        for i in 0..<cumulativeTimes.count {
            if cumulativeTimes[i] > time {
                section_index = i
                break
            }
        }
        newSection = section_index

        var t_diff = time
        if newSection > 0 {
            t_diff -= cumulativeTimes[newSection - 1]
        }

        for dof in 0..<degreesOfFreedom {
            let p = profiles[newSection][dof]
            var t_diff_dof = t_diff

            // Brake pre-trajectory
            if newSection == 0 && p.brake.duration > 0 {
                if t_diff_dof < p.brake.duration {
                    let index = (t_diff_dof < p.brake.t[0]) ? 0 : 1
                    if index > 0 {
                        t_diff_dof -= p.brake.t[index - 1]
                    }

                    set_integrate(
                        dof,
                        t_diff_dof,
                        p.brake.p[index],
                        p.brake.v[index],
                        p.brake.a[index],
                        p.brake.j[index]
                    )
                    continue
                } else {
                    t_diff_dof -= p.brake.duration
                }
            }

            // Non-time synchronization
            if t_diff_dof >= p.tSum.last! {
                // Keep constant acceleration
                set_integrate(
                    dof,
                    t_diff_dof - p.tSum.last!,
                    p.p.last!,
                    p.v.last!,
                    p.a.last!,
                    0.0
                )
                continue
            }

            // Find the correct time segment using upper_bound equivalent
            var index_dof = p.tSum.count
            for i in 0..<p.tSum.count {
                if p.tSum[i] > t_diff_dof {
                    index_dof = i
                    break
                }
            }

            if index_dof > 0 {
                t_diff_dof -= p.tSum[index_dof - 1]
            }

            set_integrate(
                dof,
                t_diff_dof,
                p.p[index_dof],
                p.v[index_dof],
                p.a[index_dof],
                p.j[index_dof]
            )
        }
    }

    /// Get the kinematic state, the jerk, and the section at a given time
    func atTime(
        _ time: Double,
        newPosition: inout [Double],
        newVelocity: inout [Double],
        newAcceleration: inout [Double],
        newJerk: inout [Double],
        newSection: inout Int
    ) throws {
        if degreesOfFreedom != newPosition.count || degreesOfFreedom != newVelocity.count
            || degreesOfFreedom != newAcceleration.count || degreesOfFreedom != newJerk.count
        {
            throw OTGErrors.runtimeError("mismatch in degrees of freedom (vector size).")
        }

        stateToIntegrateFrom(time: time, newSection: &newSection) { dof, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition[dof] = result.0
            newVelocity[dof] = result.1
            newAcceleration[dof] = result.2
            newJerk[dof] = j
        }
    }

    /// Get the kinematic state at a given time
    func atTime(
        _ time: Double,
        newPosition: inout [Double],
        newVelocity: inout [Double],
        newAcceleration: inout [Double]
    ) throws {
        if degreesOfFreedom != newPosition.count || degreesOfFreedom != newVelocity.count
            || degreesOfFreedom != newAcceleration.count
        {
            throw OTGErrors.runtimeError("mismatch in degrees of freedom (vector size).")
        }

        var newSection = 0
        stateToIntegrateFrom(
            time: time, 
            newSection: &newSection
        ) { dof, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition[dof] = result.0
            newVelocity[dof] = result.1
            newAcceleration[dof] = result.2
        }
    }

    /// Get the position at a given time
    func atTime(
        _ time: Double,
        newPosition: inout [Double]
    ) throws {
        if degreesOfFreedom != newPosition.count {
            throw OTGErrors.runtimeError("mismatch in degrees of freedom (vector size).")
        }

        var newSection = 0
        stateToIntegrateFrom(time: time, newSection: &newSection) { dof, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition[dof] = result.0
        }
    }

    /// Convenience method that returns values instead of using inout parameters
    public func atTime(_ time: Double) -> ([Double], [Double], [Double]) {
        var newPosition = Array(repeating: 0.0, count: degreesOfFreedom)
        var newVelocity = Array(repeating: 0.0, count: degreesOfFreedom)
        var newAcceleration = Array(repeating: 0.0, count: degreesOfFreedom)

        do {
            try atTime(
                time,
                newPosition: &newPosition,
                newVelocity: &newVelocity,
                newAcceleration: &newAcceleration
            )
        } catch {
            // Return zero arrays on error
        }

        return (newPosition, newVelocity, newAcceleration)
    }

    /// Single DOF variants for when degreesOfFreedom == 1
    func atTime(
        _ time: Double,
        newPosition: inout Double,
        newVelocity: inout Double,
        newAcceleration: inout Double,
        newJerk: inout Double,
        newSection: inout Int
    ) {
        guard degreesOfFreedom == 1 else { return }

        stateToIntegrateFrom(time: time, newSection: &newSection) { _, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition = result.0
            newVelocity = result.1
            newAcceleration = result.2
            newJerk = j
        }
    }

    func atTime(
        _ time: Double,
        newPosition: inout Double,
        newVelocity: inout Double,
        newAcceleration: inout Double
    ) {
        guard degreesOfFreedom == 1 else { return }

        var newSection = 0
        stateToIntegrateFrom(time: time, newSection: &newSection) { _, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition = result.0
            newVelocity = result.1
            newAcceleration = result.2
        }
    }

    func atTime(
        _ time: Double,
        newPosition: inout Double
    ) {
        guard degreesOfFreedom == 1 else { return }

        var newSection = 0
        stateToIntegrateFrom(time: time, newSection: &newSection) { _, t, p, v, a, j in
            let result = integrate(t, p, v, a, j)
            newPosition = result.0
        }
    }

    /// Get the underlying profiles of the trajectory
    public func getProfiles() -> [[Profile]] {
        profiles
    }

    /// Get the duration of the (synchronized) trajectory
    public func getDuration() -> Double {
        duration
    }

    /// Get the durations when the intermediate waypoints are reached
    func get_intermediate_durations() -> [Double] {
        cumulativeTimes
    }

    /// Get the minimum duration of each independent DoF
    func get_independentMinDurations() -> [Double] {
        independentMinDurations
    }

    /// Get the min/max values of the position for each DoF
    mutating func getPositionExtrema() -> [Bound] {
        // Initialize positionExtrema if needed or reset it
        positionExtrema = Array(repeating: Bound(), count: degreesOfFreedom)

        // Calculate extrema for first profile section
        for dof in 0..<degreesOfFreedom {
            positionExtrema[dof] = profiles[0][dof].getPositionExtrema()
        }

        // Merge extrema from all profile sections
        for i in 1..<profiles.count {
            for dof in 0..<degreesOfFreedom {
                let section_positionExtrema = profiles[i][dof].getPositionExtrema()

                // Update maximum if this section has a higher max
                if section_positionExtrema.max > positionExtrema[dof].max {
                    positionExtrema[dof].max = section_positionExtrema.max
                    positionExtrema[dof].tMax = section_positionExtrema.tMax
                }

                // Update minimum if this section has a lower min
                if section_positionExtrema.min < positionExtrema[dof].min {
                    positionExtrema[dof].min = section_positionExtrema.min
                    positionExtrema[dof].tMin = section_positionExtrema.tMin
                }
            }
        }

        return positionExtrema
    }

    /// Get the time that this trajectory passes a specific position of a given DoF the first time
    func get_first_time_at_position(
        dof: Int,
        position: Double,
        timeAfter: Double = 0.0
    ) -> Double? {
        if dof >= degreesOfFreedom {
            return nil
        }

        var time: Double = 0.0
        for i in 0..<profiles.count {
            if profiles[i][dof].getFirstStateAtPosition(
                pt: position,
                time: &time,
                timeAfter: timeAfter
            ) {
                let section_time = (i > 0) ? cumulativeTimes[i - 1] : 0.0
                return section_time + time
            }
        }
        return nil
    }
}
